        ) {
          continue;
        }
        players.push(candidate);
        await this.store.removeEntry(candidate.identity.id);
      }
      const updated: MatchProposal = {
        ...proposal,
        players,
        acceptedIds: [],
        expiresAt: players.length === proposal.finalSize ? now + CONFIRMATION_MS : null,
      };
